INSERT INTO brands(name,slug,description,is_active) VALUES('Luxe Atelier Demo','luxe-atelier-demo','Sample brand for local development.',TRUE);
INSERT INTO categories(name,slug,description,sort_order,is_active) VALUES('Floral','floral','Demo category',1,TRUE),('Woody','woody','Demo category',2,TRUE),('Amber','amber','Demo category',3,TRUE),('Citrus','citrus','Demo category',4,TRUE);
INSERT INTO collections(name,slug,description,is_active) VALUES('Signature Demo Collection','signature-demo-collection','Sample collection only.',TRUE);
INSERT INTO products(category_id,brand_id,name,slug,short_description,description,product_type,status,is_featured) SELECT c.id,b.id,'Demo Floral Eau de Parfum','demo-floral-eau-de-parfum','Illustrative sample; replace with approved content.','Development seed only.','VARIABLE','ACTIVE',TRUE FROM categories c CROSS JOIN brands b WHERE c.slug='floral' AND b.slug='luxe-atelier-demo';
INSERT INTO products(category_id,brand_id,name,slug,short_description,description,product_type,status,is_featured) SELECT c.id,b.id,'Demo Woody Eau de Parfum','demo-woody-eau-de-parfum','Illustrative sample; replace with approved content.','Development seed only.','VARIABLE','ACTIVE',FALSE FROM categories c CROSS JOIN brands b WHERE c.slug='woody' AND b.slug='luxe-atelier-demo';
INSERT INTO product_images(product_id,image_url,alt_text,sort_order,is_primary) SELECT id,'https://placehold.co/800x1000?text=Demo+Floral','Demo floral placeholder',0,TRUE FROM products WHERE slug='demo-floral-eau-de-parfum';
INSERT INTO product_images(product_id,image_url,alt_text,sort_order,is_primary) SELECT id,'https://placehold.co/800x1000?text=Demo+Woody','Demo woody placeholder',0,TRUE FROM products WHERE slug='demo-woody-eau-de-parfum';
INSERT INTO product_variants(product_id,sku,variant_name,option_values,volume_ml,price,compare_at_price,is_default,is_active) SELECT id,'DEMO-FLORAL-050','50 ml',JSON_OBJECT('volume','50 ml'),50,2500,2800,TRUE,TRUE FROM products WHERE slug='demo-floral-eau-de-parfum';
INSERT INTO product_variants(product_id,sku,variant_name,option_values,volume_ml,price,compare_at_price,is_default,is_active) SELECT id,'DEMO-WOODY-050','50 ml',JSON_OBJECT('volume','50 ml'),50,2900,3200,TRUE,TRUE FROM products WHERE slug='demo-woody-eau-de-parfum';
INSERT INTO inventory(variant_id,quantity_on_hand,quantity_reserved,reorder_level) SELECT id,25,0,5 FROM product_variants WHERE sku='DEMO-FLORAL-050';
INSERT INTO inventory(variant_id,quantity_on_hand,quantity_reserved,reorder_level) SELECT id,15,0,4 FROM product_variants WHERE sku='DEMO-WOODY-050';
INSERT INTO inventory_movements(variant_id,movement_type,quantity_change,reference_type,note) SELECT id,'RECEIPT',25,'SEED','Demo initial stock' FROM product_variants WHERE sku='DEMO-FLORAL-050';
INSERT INTO inventory_movements(variant_id,movement_type,quantity_change,reference_type,note) SELECT id,'RECEIPT',15,'SEED','Demo initial stock' FROM product_variants WHERE sku='DEMO-WOODY-050';
INSERT INTO collection_products(collection_id,product_id,sort_order) SELECT c.id,p.id,1 FROM collections c CROSS JOIN products p WHERE c.slug='signature-demo-collection' AND p.slug='demo-floral-eau-de-parfum';
INSERT INTO collection_products(collection_id,product_id,sort_order) SELECT c.id,p.id,2 FROM collections c CROSS JOIN products p WHERE c.slug='signature-demo-collection' AND p.slug='demo-woody-eau-de-parfum';
